import React from 'react';
import {
  LayoutDashboard, Calendar, BarChart3,
  Trophy, Settings, Flame, Zap, Star
} from 'lucide-react';

interface SidebarProps {
  currentView: string;
  setCurrentView: (v: string) => void;
  darkMode: boolean;
  setDarkMode: (d: boolean) => void;
  points: number;
  streak: number;
}

const menuItems = [
  { id: 'dashboard', label: 'Dashboard',  icon: LayoutDashboard },
  { id: 'calendar',  label: 'Calendar',   icon: Calendar         },
  { id: 'reports',   label: 'Analytics',  icon: BarChart3        },
  { id: 'rewards',   label: 'Rewards',    icon: Trophy           },
  { id: 'settings',  label: 'Settings',   icon: Settings         },
];

const categoryColors: Record<string, string> = {
  dashboard: '#4F8EF7',
  calendar:  '#22D3EE',
  reports:   '#10B981',
  rewards:   '#F59E0B',
  settings:  '#8B5CF6',
};

const Sidebar: React.FC<SidebarProps> = ({
  currentView, setCurrentView, darkMode, setDarkMode, points, streak
}) => {
  return (
    <aside className="sidebar" style={{ width: 260, height: '100vh', position: 'sticky', top: 0, display: 'flex', flexDirection: 'column', padding: '28px 18px', zIndex: 50, flexShrink: 0 }}>
      {/* Background orbs */}
      <div className="orb" style={{ width: 200, height: 200, background: '#4F8EF7', top: -80, left: -60, opacity: 0.07 }} />
      <div className="orb" style={{ width: 150, height: 150, background: '#8B5CF6', bottom: 80, right: -40, opacity: 0.07 }} />

      {/* Logo */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 36, paddingLeft: 6 }}>
        <div style={{ width: 42, height: 42, borderRadius: 14, background: 'linear-gradient(135deg,#4F8EF7,#8B5CF6)', display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 0 20px rgba(79,142,247,0.4)', flexShrink: 0 }}>
          <Flame size={22} fill="#fff" color="#fff" />
        </div>
        <div>
          <div style={{ fontFamily: "'Space Grotesk',sans-serif", fontWeight: 700, fontSize: 16, color: '#F1F5F9', lineHeight: 1.2 }}>180-Day</div>
          <div style={{ fontSize: 10, color: '#4F8EF7', fontWeight: 700, letterSpacing: '0.12em', textTransform: 'uppercase' }}>Challenge</div>
        </div>
      </div>

      {/* Nav */}
      <nav style={{ display: 'flex', flexDirection: 'column', gap: 4, flex: 1 }}>
        {menuItems.map(({ id, label, icon: Icon }) => {
          const isActive = currentView === id;
          const color = categoryColors[id];
          return (
            <button
              key={id}
              onClick={() => setCurrentView(id)}
              className="nav-btn"
              style={isActive ? {
                color: '#fff',
                background: `linear-gradient(135deg, ${color}22, ${color}11)`,
                borderColor: `${color}44`,
              } : {}}
            >
              {isActive && (
                <span style={{ position: 'absolute', left: 0, top: '18%', height: '64%', width: 3, background: `linear-gradient(180deg,${color},${color}88)`, borderRadius: '0 4px 4px 0' }} />
              )}
              <span style={{ width: 34, height: 34, borderRadius: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', background: isActive ? `${color}22` : 'rgba(255,255,255,0.03)', border: `1px solid ${isActive ? color+'33' : 'rgba(255,255,255,0.06)'}`, flexShrink: 0, transition: 'all 0.2s' }}>
                <Icon size={16} color={isActive ? color : '#64748B'} />
              </span>
              <span style={{ fontWeight: 600, fontSize: 13 }}>{label}</span>
              {isActive && <span style={{ marginLeft: 'auto', width: 6, height: 6, borderRadius: '50%', background: color, boxShadow: `0 0 8px ${color}`, flexShrink: 0 }} />}
            </button>
          );
        })}
      </nav>

      {/* Stats card */}
      <div className="card-static" style={{ padding: '18px', marginBottom: 12 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
          <div>
            <div style={{ fontSize: 10, color: '#475569', fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 4 }}>Total Points</div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              <span style={{ fontFamily: "'Space Grotesk',sans-serif", fontSize: 28, fontWeight: 700, color: '#F1F5F9', lineHeight: 1 }}>{points.toLocaleString()}</span>
              <Zap size={16} fill="#F59E0B" color="#F59E0B" />
            </div>
          </div>
          <div style={{ textAlign: 'right' }}>
            <div style={{ fontSize: 10, color: '#475569', fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 4 }}>Streak</div>
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, justifyContent: 'flex-end' }}>
              <span style={{ fontFamily: "'Space Grotesk',sans-serif", fontSize: 22, fontWeight: 700, color: '#F59E0B', lineHeight: 1 }}>{streak}</span>
              <Flame size={16} fill="#F59E0B" color="#F59E0B" />
            </div>
          </div>
        </div>
        <div>
          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6, fontSize: 11, color: '#475569', fontWeight: 600 }}>
            <span>Next Badge</span>
            <span>{Math.min(Math.round((streak / 7) * 100), 100)}%</span>
          </div>
          <div className="progress-bar-track" style={{ height: 6 }}>
            <div className="progress-bar-fill" style={{ width: `${Math.min((streak / 7) * 100, 100)}%`, background: 'linear-gradient(90deg,#4F8EF7,#8B5CF6)' }} />
          </div>
        </div>
      </div>

      {/* Dark mode toggle */}
      <button
        onClick={() => setDarkMode(!darkMode)}
        style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 14px', borderRadius: 14, background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)', cursor: 'pointer', transition: 'all 0.2s', color: '#64748B' }}
        onMouseEnter={e => (e.currentTarget.style.background = 'rgba(255,255,255,0.06)')}
        onMouseLeave={e => (e.currentTarget.style.background = 'rgba(255,255,255,0.03)')}
      >
        <span style={{ fontSize: 13, fontWeight: 600, color: '#94A3B8' }}>{darkMode ? '🌙 Dark Mode' : '☀️ Light Mode'}</span>
        <div className={`toggle ${darkMode ? 'on' : 'off'}`}>
          <div className="toggle-thumb" />
        </div>
      </button>
    </aside>
  );
};

// Mobile bottom nav
export const MobileNav: React.FC<{ currentView: string; setCurrentView: (v: string) => void }> = ({ currentView, setCurrentView }) => (
  <div className="mobile-nav">
    {menuItems.map(({ id, label, icon: Icon }) => {
      const isActive = currentView === id;
      return (
        <button
          key={id}
          onClick={() => setCurrentView(id)}
          style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4, padding: '8px 4px', borderRadius: 10, background: isActive ? 'rgba(79,142,247,0.1)' : 'transparent', border: `1px solid ${isActive ? 'rgba(79,142,247,0.3)' : 'transparent'}`, cursor: 'pointer', color: isActive ? '#4F8EF7' : '#475569', transition: 'all 0.2s' }}
        >
          <Icon size={20} />
          <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: '0.05em', textTransform: 'uppercase' }}>{label}</span>
        </button>
      );
    })}
  </div>
);

export default Sidebar;
